26	        // Record how many existing owners already share this first+last name (case-insensitive),
27	        // counted before this owner is persisted so the value is fixed at creation time.
28	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName(), ownerRepository));
29	        // Join a shared household when the gate resolved an identifier.
30	        if (householdId != null && householdId.isPresent()) {
31	            owner.setHouseholdId(householdId.value());
32	        }
33	        // Record the household's member count (existing members plus this not-yet-persisted
34	        // owner) so the membership points rule can score a household of 3 or more.
35	        owner.setHouseholdSize(Household.size(owner.getHouseholdId(), ownerRepository) + 1);
